def classify_status(status_code):
    from orgops.metrics import emit
    if 400 <= status_code < 500:
        emit("classification", "4xx")
        return "4xx"
    elif 500 <= status_code < 600:
        emit("classification", "5xx")
        return "5xx"
    else:
        emit("classification", "unknown")
        return "unknown"
